const seedsByPackAndDifficulty: Readonly<Record<string, readonly CategorySeed[]>> = {
  'built-in-art-architecture/medium': artMedium,
  'built-in-art-architecture/hard': artHard,
  'built-in-music/medium': musicMedium,
  'built-in-music/hard': musicHard,
  'built-in-film-television/medium': screenMedium,
  'built-in-film-television/hard': screenHard,
  'built-in-sports-games/medium': sportsMedium,
  'built-in-sports-games/hard': sportsHard,
};

const lanePackIds = new Set([
  'built-in-art-architecture',
  'built-in-music',
  'built-in-film-television',
  'built-in-sports-games',
]);

const sourceId = (page: string): string => `wikipedia:${page
  .toLocaleLowerCase('en')
  .replace(/[^a-z0-9]+/gu, '-')
  .replace(/^-|-$/gu, '')}`;

const makeQuestion = (
  target: PlayableTarget,
  seed: CategorySeed,
  question: QuestionSeed,
): PlayableQuestion => {
  const [
    subjectKey,
    sourcePage,
    tier,
    responseEn,
    responseEt,
    clueEn,
    clueEt,
    explanationEn,
    explanationEt,
    variantsEn,
    variantsEt,
  ] = question;
  const sourceTitle = decodeURIComponent(sourcePage).replaceAll('_', ' ');
  return {
    key: `${target.categorySetId}:tier-${tier}`,
    factKey: `${subjectKey}:${seed.relation}`,
    tier,
    subjectKey,
    clue: { en: clueEn, et: clueEt },
    response: { en: responseEn, et: responseEt },
    acceptedVariants: { en: variantsEn, et: variantsEt },
    explanation: { en: explanationEn, et: explanationEt },
    source: {
      sourceId: sourceId(sourcePage),
      title: `${sourceTitle} — Wikipedia`,
      url: `https://en.wikipedia.org/wiki/${sourcePage}`,
      license: 'CC BY-SA 4.0',
      retrievedAt: '2026-08-28',
    },
  };
};

const laneTargets = PLAYABLE_TARGETS.filter(({ packId }) => lanePackIds.has(packId));
const nextSeedIndex = new Map<string, number>();

const categories = laneTargets.map((target) => {
  const groupKey = `${target.packId}/${target.difficulty}`;
  const seeds = seedsByPackAndDifficulty[groupKey];
  const index = nextSeedIndex.get(groupKey) ?? 0;
  const seed = seeds?.[index];
  if (seed === undefined) {
    throw new Error(`Missing category seed ${index + 1} for ${groupKey}`);
  }
  nextSeedIndex.set(groupKey, index + 1);
  return {
    categorySetId: target.categorySetId,
    batchId: target.batchId,
    packId: target.packId,
    difficulty: target.difficulty,
    name: { en: seed.nameEn, et: seed.nameEt },
    questions: seed.questions.map((question) => makeQuestion(target, seed, question)),
  };
});

for (const [groupKey, seeds] of Object.entries(seedsByPackAndDifficulty)) {
  const consumed = nextSeedIndex.get(groupKey) ?? 0;
  if (consumed !== seeds.length) {
    throw new Error(`Surplus category seeds for ${groupKey}: consumed ${consumed} of ${seeds.length}`);
  }
}

export const PACKS_05_TO_08_CATEGORIES: readonly PlayableCategory[] = categories;
